89:         public bool CheckOperatingEnvironment()
90:         {
91:             // 晶圆域有没有准备好
92:             if (!WaferSystemDomain.GetInstance().CheckIsReady())
93:             {
94:                 return false;
95:             }
96: 
97:             // 固晶域启动自检
