99:             {
100:                 return false;
101:             }
102: 
103:             // 点胶域有没有准备好
104:             if (!System1Domain.GetInstance().CheckIsReady())
105:             {
106:                 return false;
107:             }
108: 
109:             // 产品有没有准备好
110:             if (!ProductConfiguration.GetInstance().IsTransportUnitReady())
111:             {
112:                 return false;
113:             }
114: 
115:             // 焊点有没有准备好
116:             if (!ProductConfiguration.GetInstance().BondPositionConfig.IsBpAssistanceFinish())
117:             {
118:                 return false;
119:             }
120: 
121:             // 制程是否准备好
122:             if (!ProcessDomain.GetInstance().CheckIsReady())
123:             {
124:                 return false;
125:             }
126: 
127:             return true;
128:         }

