658:             if (ForceConfig.GetInstance().IsEmpty())
659:             {
660:                 foreach (var item in WaferSystemProgram.GetInstance().GetCarriers())
661:                 {
662:                     if (item.IsUseForceControl)
663:                     {
664:                         AKRSXtraMessageBox.Show(
665:                             $"芯片:{item.Name} 有使用力控功能，启动前请先进行力控标定!",
