676:             if (System2Configuration.GetInstance().IsActiveDriftCompensate)
677:             {
678:                 if (this.BondDevicePara.BondHeadParam.UpLookMarkVisionPos1.IsEmpty)
679:                 {
680:                     AKRSXtraMessageBox.Show(
681:                         $"启动前请先示教温漂定位的点位!",
682:                         "错误",
683:                         MessageBoxButtons.OK,
684:                         MessageBoxIcon.Error);
685: 
686:                     return false;
687:                 }
688:             }
689: 
690:             // 检查温漂点位
691:             if (System2Configuration.GetInstance().IsActivePickUpCompensate)
692:             {
693:                 if (this.BondDevicePara.BondHeadParam.PickMarkVisionPos1.IsEmpty)
694:                 {
695:                     AKRSXtraMessageBox.Show(
696:                         $"启动前请先示教取片偏移的点位!",
697:                         "错误",
698:                         MessageBoxButtons.OK,
699:                         MessageBoxIcon.Error);
700: 
701:                     return false;
702:                 }
703:             }
704: 
705:             // 先检查吸嘴架硬件
706:             if (!this.NozzleShelfController.CheckToolBankConfiguration())
707:             {
708:                 return false;
709:             }
710: 
711:             if (System2Configuration.GetInstance().IsActiveToolDetection)
712:             {
713:                 // 1.是否有touchdown  2.所需要的吸嘴是否在吸嘴架上
714:                 // 判断焊头上有没有吸嘴， 如果有和tool bank的配置是否对应 如果不对应则报警，如果对应则先放回去。
715:                 bool isToolOnHeadLogic = this.BondHeadController.IsToolOnBondheadLogic();
716:                 bool isToolOnHeadPhy = this.BondHeadController.IsToolOnBondheadPhy();
717: 
718:                 ret = isToolOnHeadLogic == isToolOnHeadPhy;
719: 
720:                 if (isToolOnHeadPhy == true && isToolOnHeadLogic == false)
721:                 {
722:                     AKRSXtraMessageBox.Show(
723:                         $"焊头上检测到吸嘴，与程式冲突!",
724:                         "错误",
725:                         MessageBoxButtons.OK,
726:                         MessageBoxIcon.Error);
727: 
728:                     return false;
729:                 }
730:                 else if (isToolOnHeadPhy == false && isToolOnHeadLogic == true)
731:                 {
732:                     // 如果焊头检测没有，但记忆中有吸嘴
733:                     if (AKRSXtraMessageBox.Show(
734:                             $"焊头上没有检测到吸嘴，与程式冲突!\r\nYes:设置焊头上没有吸嘴\r\nNo:终止工作",
735:                             "错误",
736:                             MessageBoxButtons.YesNo,
737:                             MessageBoxIcon.Question) == DialogResult.Yes)
738:                     {
739:                         this.BondHeadController.SetCurrentNozzleName(string.Empty);
740:                     }
741:                     else
742:                     {
743:                         return false;
744:                     }
745:                 }
746:             }
747: 
748: 
749:             // 检查焊头上是否有料
750:             if (System2RunTimeProvider.IsMaterialOnBondhead)
751:             {
752:                 DialogResult dia = AKRSXtraMessageBox.Show(
753:                     $"记忆中吸嘴上有料，请选择如何处理!\r\nOK:抛料\r\nNo:忽略",
754:                     "错误",
755:                     MessageBoxButtons.OKCancel,
756:                     MessageBoxIcon.Question);
757: 
758:                 if (dia == DialogResult.OK)
759:                 {
760:                     this.BondModuleController.ThrowAction();
761:                 }
762:             }
763: 
764:             // 预点胶是否可以执行
765:             if (this.BondActionNodeRepository.S2PreDispenseActionNode.IsAlarm())
766:             {
767:                 return false;
768:             }
769: 
770:             return true;

