217:         public void OpenBondHeadVaccum()
218:         {
219:             if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.OffLineWork)
220:             {
221:                 return;
222:             }
223: 
224:             // 单步工作
225:             if (!System2Domain.GetInstance().WaitSingleStep())
226:             {
227:                 return;
228:             }
229: 
230:             // 已经开了就不开
231:             if (this.GetBondheadVacuumState())
232:             {
233:                 return;
234:             }
235: 
236:             this.bondHead.BondHeadVaccumElectric.SetOutputValue(true);
237:         }

777:         public bool WaitSingleStep()
