85:         public bool SelfCheck()
86:         {
87:             if (!this.NozzleShelfProgram.SelfCheck())
88:             {
89:                 return false;
90:             }
91: 
92:             // 遍历所有芯片
93:             foreach (BaseCarrierConfig carrier in WaferSystemProgram.GetInstance().GetCarriers())
94:             {
95:                 if (string.IsNullOrEmpty(carrier.NozzleName))
96:                 {
97:                     DialogResult dialog = AKRSXtraMessageBox.Show(
98:                         $"芯片:{carrier.Name}未配置吸嘴!\r\n  请先示教芯片!",
99:                         "Warn",
100:                         MessageBoxButtons.OK,
101:                         MessageBoxIcon.Warning);
102: 
103:                     return false;
104:                 }
105: 
106:                 if (carrier.BondingForceMode == ForceModeEnum.Force)
107:                 {
108:                     if (carrier.BondingForce <= BondDevicePara.GetInstance().BondHeadParam.ForceControlMinVal || carrier.BondingForce >= BondDevicePara.GetInstance().BondHeadParam.ForceControlMaxVal)
109:                     {
110:                         DialogResult dialog = AKRSXtraMessageBox.Show(
111:                             $"芯片:{carrier.Name}  贴片力:{carrier.BondingForce}g 超限!力控范围：{BondDevicePara.GetInstance().BondHeadParam.ForceControlMinVal}g~{BondDevicePara.GetInstance().BondHeadParam.ForceControlMaxVal}g\r\n请检查参数设置!",
112:                             "Warn",
113:                             MessageBoxButtons.OK,
114:                             MessageBoxIcon.Warning);
115: 
116:                         return false;
117:                     }
118:                 }
119: 
120:                 if (carrier.PickupForceMode == ForceModeEnum.Force)
121:                 {
