123:                     {
124:                         DialogResult dialog = AKRSXtraMessageBox.Show(
125:                             $"芯片:{carrier.Name}  取片力:{carrier.PickupForce}g 超限!力控范围：{BondDevicePara.GetInstance().BondHeadParam.ForceControlMinVal}g~{BondDevicePara.GetInstance().BondHeadParam.ForceControlMaxVal}g\r\n请检查参数设置!",
