676:             if (System2Configuration.GetInstance().IsActiveDriftCompensate)
677:             {
678:                 if (this.BondDevicePara.BondHeadParam.UpLookMarkVisionPos1.IsEmpty)
679:                 {
680:                     AKRSXtraMessageBox.Show(
