824: 
825:             //this.bondHeadController.CloseToolBlowEle();
826: 
827:             // 设置回弱吹
828:             this.bondHeadController.SetBlowProportion(curProportion);
829: 
830:             Thread.Sleep(this.bondDevicePara.BondHeadParam.ThrowBlowDelay);
831: 
832:             this.bondHeadController.CloseToolBlowEle();
833: 
