341:                 TransportDomain.GetInstance().TransportProgram.BondSubSectionProgram.TransportUnit;
342: 
343:             // 当前位置
344:             AKRSPoint3D curPos = this.bondModule.Get3DRealPosition();
345: 
346:             // 安全高度转到G0坐标系
347:             double safeHeight = this.bondModule.BondCoordinateSystem
348:                 .SelfPosToG0(this.bondDevicePara.BondHeadParam.AxisSafePos).Z;
349: 
350:             if (transportUnit != null)
