358:                                  + ProductConfiguration.GetInstance().TransportUnitConfig.SafeHeight - System2Domain
359:                                      .GetInstance().S2DispenseController.DistanceForBondHandAndDispenser.Z;
360:                 }
361:                 else
362:                 {
363:                     safeHeight = transportUnit.CoordinateSystem.SelfPosToG0(new AKRSPoint3D()).Z
364:                                  + ProductConfiguration.GetInstance().TransportUnitConfig.SafeHeight
365:                                  + (this.bondModule.BondHead.CurrentNozzle?.MeasureHeightOffset ?? 0);
