45:         /// <summary>
46:         /// 点胶动作
47:         /// </summary>
48:         /// <returns>结果</returns>
49:         public override ExcuteResult DoWork()
50:         {
51:             this.WorkStart?.Invoke();
52:             this.State = RunStateEnum.Running;
53:             try
54:             {
55:                 System2RunTimeProvider.RecordTime("系统2点胶动作开始执行", "开始 ----------------");
56: 
57:                 #region 前提条件判断
58: 
59:                 // 单步工作
60:                 if (!System2Domain.GetInstance().WaitSingleStep())
61:                 {
62:                     return ExcuteResult.Abort;
63:                 }
64: 
65:                 // 执行点胶前如果点了停止则退出
66:                 if (!Signal.WaitStart())
67:                 {
68:                     return ExcuteResult.Fail;
69:                 }
70: 
71:                 // 执行预点胶
72:                 if (System2Domain.GetInstance().BondActionNodeRepository.S2PreDispenseActionNode.DoWork() != ExcuteResult.Success)
73:                 {
74:                     return ExcuteResult.Alarm;
75:                 }
76: 
77:                 if (!Signal.WaitStart())
78:                 {
79:                     return ExcuteResult.Fail;
80:                 }
81: 
82:                 #endregion
83: 
84:                 System2RunTimeProvider.RecordTime("点胶前置条件通过，准备开始", "开始 ----------------");
85: 
86:                 // 焊点
87:                 BondPosition bondPosition = this.ActionNodesService.GetCurrentBondPosition();
88: 
89:                 // 获取需要执行的图案
90:                 EpoxyApplication correctApplication = this.ActionNodesService.GetCurrentEpoxyApplication();
91: 
92:                 // 焊点在G0中的位置
93:                 AKRSPoint3D point = bondPosition.CoordinateSystem.SelfPosToG0(new AKRSPoint3D(correctApplication.OffsetX, correctApplication.OffsetY, 0));
94: 
95:                 point += bondPosition.GetDispensePositionCompensate();
96: 
97:                 // 空跑模式不出胶
98:                 bool isDrip = MachineStateModel.GetInstance().MachineWorkMode != MachineWorkModeEnum.DryCycle;
99: 
100:                 double angle = bondPosition.CoordinateSystem.DegreeInG0() * 180.0 / Math.PI + bondPosition.GetDispenseRotaryCompensate();
101: 
102:                 #region 更换蘸胶吸嘴
103: 
104:                 if (correctApplication.EpoxyApplicationStrategy == EpoxyApplicationTypeEnum.Printting)
105:                 {
106:                     Nozzle nozzle = System2Domain.GetInstance().BondProgram.NozzleShelfProgram.GetNozzleList().Find(it => it.Name == correctApplication.PrintNozzleName);
107:                     if (nozzle == null)
108:                     {
109:                         throw new Exception("蘸胶吸嘴为空，请重新选择");
