91: 
92:                 // 焊点在G0中的位置
93:                 AKRSPoint3D point = bondPosition.CoordinateSystem.SelfPosToG0(new AKRSPoint3D(correctApplication.OffsetX, correctApplication.OffsetY, 0));
94: 
95:                 point += bondPosition.GetDispensePositionCompensate();
96: 
97:                 // 空跑模式不出胶
98:                 bool isDrip = MachineStateModel.GetInstance().MachineWorkMode != MachineWorkModeEnum.DryCycle;
99: 
100:                 double angle = bondPosition.CoordinateSystem.DegreeInG0() * 180.0 / Math.PI + bondPosition.GetDispenseRotaryCompensate();
101: 
102:                 #region 更换蘸胶吸嘴
103: 
104:                 if (correctApplication.EpoxyApplicationStrategy == EpoxyApplicationTypeEnum.Printting)
105:                 {
106:                     Nozzle nozzle = System2Domain.GetInstance().BondProgram.NozzleShelfProgram.GetNozzleList().Find(it => it.Name == correctApplication.PrintNozzleName);
107:                     if (nozzle == null)
108:                     {
109:                         throw new Exception("蘸胶吸嘴为空，请重新选择");
110:                     }
111:                     else if (!nozzle.IsAssistantSucceed)
112:                     {
113:                         throw new Exception("蘸胶吸嘴未示教完成，请示教完后重试");
114:                     }
115: 
116:                     // 换吸嘴动作
117:                     bool ret = System2Domain.GetInstance().System2Controller.JudgeAndChangeNozzle(correctApplication.PrintNozzleName);
118:                     if (!ret)
119:                     {
120:                         return ExcuteResult.Abort;
121:                     }
122:                 }
123: 
124:                 #endregion
125: 
126:                 // 执行点胶
127:                 if (System2Domain.GetInstance().S2DispenseController.InterpolationApplication(correctApplication, point, isDrip, false, false, angle) != ExcuteResult.Success)
128:                 {
129:                     return ExcuteResult.Alarm;
130:                 }
131: 
132:                 // 修改当前焊点的状态为点胶完成
133:                 bondPosition.S2FinishedStep(this.ActionNodesService.GetCurrentProcessStepName());
134: 
135:                 StatisticsDomain.GetInstance().RefreshDispenseStatistics();

175:                 return ExcuteResult.Success;
176:             }
177:             catch (Exception ex)
178:             {
179:                 LogHelper.Post(Level.Error, $"流程运行故障！", ex, LogCategory.Bond);
180:                 AKRSMessageBoxExt.Show(ex.Message, "异常", new string[] { "异常" }, new DialogResult[] { DialogResult.Yes });
181:                 return ExcuteResult.Exception;
182:             }
