278: 
279:                                     System2RunTimeProvider.RecordTime("Bond线程", "返回：ExcuteResult.Alarm");
280: 
281:                                     string message =
282:                                         $"系统2 ：{actionNode.Name} 流程运行失败！请选择如何处理！\r\n";
