211:                     #region 循环执行动作节点
212: 
213:                     // 遍历所有bondActionNodeMessages
214:                     while (Signal.WaitStart())
215:                     {
216:                         ActionNode actionNode = this.system2Domain.ActionNodesService.GetNextActionNode();
217: 
218:                         // 所有动作做完
219:                         if (actionNode == null)
220:                         {
221:                             break;
222:                         }
223:                         
224:                         RetryCommand:
225:                      
226:                         if (actionNode.IsDoWork())
227:                         {
228:                             System2RunTimeProvider.RecordTime("动作流程", $"开始执行动作{actionNode.Name}");
229: 
230:                             this.CloseDispenseCylinder(actionNode);
231: 
232:                             ExcuteResult ret = actionNode.DoWork();
233: 
234:                             switch (ret)
235:                             {
236:                                 case ExcuteResult.Abort:
237: 
238:                                     System2RunTimeProvider.RecordTime("Bond线程", "返回：ExcuteResult.Abort");
239: 
240:                                     Machine.GetInstance().Stop();
241: 
242:                                     // 焊头去安全高度
243:                                     this.bondHeadController.MoveBondZToSafePos();
244: 
245:                                     if (MachineHardwareConfiguration.GetInstance().IsSlideFluxerConfigured)
246:                                     {
247:                                         // 胶盘缩回
248:                                         this.slideFluxerController.SlideFluxerHomeWaitArrive();
249:                                     }
250: 
251:                                     return;
252: 
253:                                 case ExcuteResult.Retry:
254: 
255:                                     System2RunTimeProvider.RecordTime("Bond线程", "返回：ExcuteResult.Retry");
256: 
257:                                     // 重试不结束当前动作节点
258:                                     continue;
259: 
260:                                 case ExcuteResult.Exception:
261: 
262:                                     System2RunTimeProvider.RecordTime("Bond线程", "返回：ExcuteResult.Exception");
263: 
264:                                     Machine.GetInstance().Stop();
265: 
266:                                     // 焊头去安全高度
267:                                     this.bondHeadController.MoveBondZToSafePos();
268: 
269:                                     if (MachineHardwareConfiguration.GetInstance().IsSlideFluxerConfigured)
270:                                     {
271:                                         // 胶盘缩回
272:                                         this.slideFluxerController.SlideFluxerHomeWaitArrive();
273:                                     }
274: 
275:                                     return;
276: 
277:                                 case ExcuteResult.Alarm:
278: 
279:                                     System2RunTimeProvider.RecordTime("Bond线程", "返回：ExcuteResult.Alarm");
280: 
281:                                     string message =
282:                                         $"系统2 ：{actionNode.Name} 流程运行失败！请选择如何处理！\r\n";
283: 
284:                                     DialogResult dialogResult = AKRSMessageBoxExt.Show(
285:                                         message,
286:                                         "报警",
287:                                         new string[] { "终止", "重试", "忽略" },
288:                                         new DialogResult[] { DialogResult.Abort, DialogResult.Retry, DialogResult.Ignore },
289:                                         AlarmLevel.SecondLevel);
290: 
291:                                     switch (dialogResult)
292:                                     {
293:                                         case DialogResult.Abort:
294:                                             Machine.GetInstance().Stop();
295: 
296:                                             // 焊头去安全高度
297:                                             this.bondHeadController.MoveBondZToSafePos();
298: 
299:                                             if (MachineHardwareConfiguration.GetInstance().IsSlideFluxerConfigured)
300:                                             {
301:                                                 // 胶盘缩回
302:                                                 this.slideFluxerController.SlideFluxerHomeWaitArrive();
303:                                             }
304: 
305:                                             return;
306: 
307:                                         case DialogResult.Retry:
308:                                             goto RetryCommand;
309: 
310:                                         case DialogResult.Ignore:
311:                                             break;
312:                                     }
313: 
314:                                     break;
315:                             }
316:                         }
317: 
318:                         // 结束当前动作节点
319:                         this.system2Domain.ActionNodesService.FinishCurrentActionNode();
320: 
321:                         // Todo:点暂停Z轴抬起
322:                         //if (MachineStateModel.GetInstance().MachineState == MachineStateEnum.Pause)
323:                         //{
324:                         //    this.bondHeadController.MoveBondZToSafePos();
325:                         //}
326:                     }
327:                     #endregion
328:                 }
329: 
330:                 // Bond模组去安全位
331:                 this.bondModuleController.MoveToSafePos();
332: 
333:                 // 整个产品做完
334:                 this.system2Domain.ActionNodesService.Finish();
335:                 System2RunTimeProvider.RecordTime("Bond线程", "整个产品做完");
336: 
337:                 DefectCompensate.NormalizationOffset(this.transportUnit.Name);
338:                 System2RunTimeProvider.RecordTime("Bond线程", "归一化焊后补偿完成");
339: 
340:                 if (System2Configuration.GetInstance().IsSaveEjectionTimeData)
341:                 {
342:                     // 保存顶起缩回耗时
343:                     System2RunTimeProvider.SaveEjectionTime();
344:                     System2RunTimeProvider.RecordTime("Bond线程", "保存顶针耗时完成");
345:                 }
346: 
347:                  this.SendAway();
348:                 System2RunTimeProvider.RecordTime("Bond线程", "送走载具完成");
349: 
350:                 UcMainSystem.ReFreshSystem2TuAction();
351:                 System2RunTimeProvider.RecordTime("Bond线程", "刷新主界面UI显示完成");
352: 
353:                 // 自动工作结束，把当前吸嘴放回吸嘴架，暂时还不知道怎么判断
354:             }
355:         }

