150:         public bool IsExistTu => this.transportProgram.LoadingSubSectionProgram.TransportUnit != null
151:             || this.transportProgram.DispenseSubSectionProgram.TransportUnit != null
152:             || this.transportProgram.BondSubSectionProgram.TransportUnit != null
153:             || this.transportProgram.WaitingUnloadSubSectionProgram.TransportUnit != null
154:             || this.transportProgram.UnloadingSubSectionProgram.TransportUnit != null;
155: 
156:         /// <summary>
157:         /// 流道复位
158:         /// </summary>
159:         public void InitializeTS()
160:         {
161:             // 如果在机器处于工作中，不能初始化流道
162:             if (Machine.GetInstance().IsWorking()
163:                 || Machine.GetInstance().IsPause())
164:             {
165:                 AKRSXtraMessageBox.Show("设备正在自动运行中，不能清空载具", "警告");
166: 
167:                 return;
168:             }
169: 
170:             DialogResult dr = AKRSXtraMessageBox.Show("清空轨道设备将不能记忆已经生产的信息，确认是否执行此操作", "提示", MessageBoxButtons.YesNo);
171:             switch (dr)
172:             {
173:                 case DialogResult.Yes:
174: 
175:                     if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.LoaderBin)
176:                     {
177:                         // 上下料仓推杆缩回
178:                         this.LoaderBinController.MovePushRodHome();
179:                         this.UnLoaderBinController.MovePushRodHome();
180:                     }
181: 
182:                     if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated)
183:                     {
184:                         System1Domain.GetInstance().DispenseController.MoveToSafePos();
185:                     }
186: 
187:                     // 点胶和bond轴移动到安全位置
188:                     System2Domain.GetInstance().BondModuleController.MoveToSafePos();
189: 
190:                     this.DispenseSubSectionController.UnClamp();
191: 
192:                     // 点胶挡料气缸 降下
193:                     this.DispenseSubSectionController.BlockCylinder1DownAndDelay(50);
194:                     this.DispenseSubSectionController.BlockCylinder2DownAndDelay(50);
195: 
196: 
197:                     this.BondSubSectionController.UnClamp();
198: 
199:                     // bond 挡料气缸 降下
200:                     this.BondSubSectionController.BlockCylinderDownAndDelay(50);
201: 
202:                     // 清空记忆状态
203:                     this.transportProgram.LoadingSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
204:                     this.transportProgram.DispenseSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
205:                     this.transportProgram.BondSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
206:                     this.transportProgram.WaitingUnloadSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
207:                     this.transportProgram.UnloadingSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
208: 
209:                     // 清空载具对象
210:                     this.transportProgram.LoadingSubSectionProgram.TransportUnit = null;
211:                     this.transportProgram.DispenseSubSectionProgram.TransportUnit = null;
212:                     this.transportProgram.BondSubSectionProgram.TransportUnit = null;
213:                     this.transportProgram.WaitingUnloadSubSectionProgram.TransportUnit = null;
214:                     this.transportProgram.UnloadingSubSectionProgram.TransportUnit = null;
215:                     this.transportProgram.Save();
216: 
217:                     AKRSXtraMessageBox.Show("传输系统清空载具完成，请手动将所有载具拿走", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
218: 
219:                     break;
220: 
221:                 case DialogResult.No:
222:                     break;
223:             }
224:         }

